INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(124457, 'ruRU', '', 'Непокорные дрогбары сбросили наши ящики с припасами на дно пропасти. К счастью, у нас есть удобный способ их вернуть...', 24330),
(124458, 'ruRU', '', 'Благодарим, защитник. Мы не позволим дрогбарам саботировать наш образ жизни. Мы — Крутогорье!', 24330),
(124459, 'ruRU', '', 'Да, и я знаю, что схождение лей-линий питает огромной силой Ночной Колодец. Обуздание такой силы опасно, но если бы она могла...', 24330),
(124460, 'ruRU', '', 'Да? Что ты хочешь узнать?', 24330),
(124461, 'ruRU', '', 'Я помню эту силу... Кель''балор! Алая Чаща — наша цель.', 24330),
(124462, 'ruRU', '', 'Ах, ты прибыл. Я ожидал найти здесь что-то, но...', 24330),
(124463, 'ruRU', '', 'Один готов, остаются два. Дай знать, когда будешь готов.', 24330),
(124464, 'ruRU', '', 'Это последний. Остался один узел, который нужно распустить, и энергия должна снова свободно потечь.$b$bНадеюсь, ты готов.', 24330),
(124477, 'ruRU', '', 'Архидруид, я наблюдал, как твоя сила растёт с каждым испытанием, что ты преодолел.', 24330),
(124478, 'ruRU', '', 'Твоё величайшее испытание близко. Ты должен очистить Азерот от порчи Легиона... раз и навсегда.', 24330),
(124479, 'ruRU', '', 'Мои последователи и я стоим с тобой, архидруид. Равновесие должно быть восстановлено!', 24330),
(124480, 'ruRU', '', 'Позволь мне помочь тебе. Моя драконья форма плохо подходит для боя в таких тесных условиях, а нас сопровождает способный защитник.', 24330),
(124486, 'ruRU', '', 'Из этой лей-линии что-то вытягивает энергию, но я не вижу... подожди! У меня есть идея.', 24330),
(124487, 'ruRU', '', 'Эти высасывающие скверну, городские нарциссы!', 24330),
(124488, 'ruRU', '', 'Кто мог оставить здесь такую оскорбительную вещь?', 24330),
(124489, 'ruRU', '', 'Хитроумное маскирующее заклинание, но что это за устройство? Будь начеку.', 24330),
(124490, 'ruRU', '', 'Что ж, это было по-детски.', 24330),
(124491, 'ruRU', '', 'Я бы ожидал такого удара ниже пояса от дворфа...', 24330),
(124492, 'ruRU', '', 'Я не понимаю этого...', 24330),
(124493, 'ruRU', '', 'Хм... они перенаправляют часть силы лей-линии прямо в Святилище Порядка.', 24330),
(124494, 'ruRU', '', 'Я не решаюсь предпринимать какие-либо действия на данный момент. Я вернусь в Шал''Аран и продолжу исследования.', 24330),
(124495, 'ruRU', '', 'Хорошо, я начну. Когда я закончу, все устройства, что мы "подстроили", перестанут работать.', 24330),
(124496, 'ruRU', '', 'Готово. Барьер должен быть снят.', 24330),
(124498, 'ruRU', '', 'Если что-то пойдёт не так, держи своих иссохших наготове. Удачи, $n.', 24330),
(124504, 'ruRU', '', 'Она ждёт тебя прямо снаружи.', 24330),
(124505, 'ruRU', '', 'Ты помнишь меня, чужак?', 24330),
(124506, 'ruRU', '', 'Плод с этого дерева вырвал меня из пасти безумия. Теперь я цел и хочу сражаться.', 24330),
(124507, 'ruRU', '', 'Мой брат покоится здесь. Моё имя — Арлуэль.', 24330),
(124509, 'ruRU', '', 'Для меня честь наконец встретиться с тобой, Первый Чародей.', 24330),
(124510, 'ruRU', '', 'Должно быть, ты сестра Арлуина. Мы в большом долгу перед ним. Его жертва не была напрасной.', 24330),
(124511, 'ruRU', '', 'Да будет так. Я отправлю тебя к Сильгрину. С его обучением ты хорошо послужишь нам.', 24330),
(124514, 'ruRU', '', 'Нас обнаружили!', 24330),
(124515, 'ruRU', '', 'Это должно бы меня потрясти, но нет. Не после Убывающего Полумесяца.', 24330),
(124516, 'ruRU', '', 'Мы должны положить этому конец.', 24330),
(124524, 'ruRU', '', 'Демонические кристаллы закрепляют здесь силу Легиона. Нам стоит посмотреть, что иссохшие могут сделать против них.', 24330),
(124527, 'ruRU', '', 'Я увидел достаточно. Полагаю, я могу ослабить воздействие демонической магии на иссохших. Иди к машине душ, и я направлю к тебе новых подопытных.', 24330),
(124530, 'ruRU', '', 'Это сработало даже лучше, чем ожидалось! Я продолжу совершенствовать свою работу для следующего шага.', 24330),
(124535, 'ruRU', '', 'Его сделают примером для всех.', 24330),
(124536, 'ruRU', '', 'Сколько у нас времени?', 24330),
(124537, 'ruRU', '', 'Я не знаю. Лишь надеюсь, что мы не слишком поздно.', 24330);
